    """Read an optional JSON body for a normally body-less route.

    Returns the parsed payload (or None when no body is present). A
    present body that is not valid JSON reports the route-neutral
    ``{"error": "request body must be valid JSON"}`` 400 only when an
    Idempotency-Key is in play (the key-less legacy behavior drains and
    ignores such a body).
    """
    if not self.headers.get("Content-Length"):
        return True, None
    ok, payload = self._read_json()
    if ok:
        return True, payload
    if self._idempotency_key() is None:
        # Preserve the legacy drain-and-ignore behavior exactly.
        return True, None
    return False, payload

def _run_mutation(
    self,
    invoke,
    payload: object,
    sort_keys: bool = True,
    ordered_error: bool = False,
    prune_syncs: bool = False,
) -> None:
    """Dispatch one state-changing POST/DELETE, honoring an optional
    Idempotency-Key.

    Without the header the business method runs and its response is
    sent verbatim (the exact legacy behavior, CLI included). With a
    valid key the request is executed through the service's unified
    idempotency unit: the first success echoes the key with
    ``Idempotency-Replayed: false``, a same-key/same-fingerprint
    retry returns the cached status and JSON with
    ``Idempotency-Replayed: true``, and a same-key/different-fingerprint
    retry is the contract's 409 conflict body.
    """
    key = self._idempotency_key()
    error_body = (
        {"ok": False, "error": "input"}
        if ordered_error
        else DEFAULT_IDEMPOTENCY_400
    )
    if key is False:
        self._send_json(400, error_body, sort_keys=False if ordered_error else True)
        return
    if key is not None and not self._valid_fingerprint_target():
        self._send_json(400, error_body, sort_keys=False if ordered_error else True)
        return
    if key is None:
        status, body = invoke()
        self._send_json(status, body, sort_keys=sort_keys)
        return
    status, body, replayed = service.run_idempotent(
        key,
        self.command,
        self.path,
        payload,
        invoke,
        sort_keys=sort_keys,
        prune_syncs=prune_syncs,
    )
    self._send_json(
        status,
        body,
        sort_keys=sort_keys,
        extra_headers=[
            (IDEMPOTENCY_HEADER, key),
            (IDEMPOTENCY_REPLAYED_HEADER, "true" if replayed else "false"),
        ],
    )

